import type { FormVariant, GeneratedFile } from "./types.ts";

/**
 * Inlines `style.css`/`data.js`/`behavior.js` into a single self-contained HTML
 * document for the live preview iframe. The iframe can't fetch same-directory
 * `ff.html`'s external `<link>`/`<script src>` references the way a real zip download
 * can, so this substitutes inline equivalents — same generated bytes, just inlined
 * rather than referenced, so the preview runs the actual generated behavior.js/data.js
 * (not a separately hand-written rendering path) and can never diverge from the
 * downloaded output.
 */
export function buildPreviewDocument(files: GeneratedFile[], variant: FormVariant, previewLocale: string): string {
  const html = files.find((f) => f.path === `${variant}.html`)?.contents;
  const css = files.find((f) => f.path === "style.css")?.contents ?? "";
  const dataJs = files.find((f) => f.path === "data.js")?.contents ?? "";
  const behaviorJs = files.find((f) => f.path === "behavior.js")?.contents ?? "";
  if (!html) throw new Error(`No generated ${variant}.html file to preview.`);

  // The preview is served from a blob: URL, which can't carry a working "?lang="
  // query string — set the override global behavior.js's getLanguage() checks first.
  const langOverride = `<script>window.__PREVIEW_LANG__ = ${JSON.stringify(previewLocale)};</script>`;

  return html
    .replace('<link rel="stylesheet" href="style.css">', `<style>${css}</style>`)
    .replace('<script src="data.js"></script>', `${langOverride}\n<script>${dataJs}</script>`)
    .replace('<script src="behavior.js"></script>', `<script>${behaviorJs}</script>`);
}
